import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-BB3YzYxd.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurer une voiture sans carte grise définitive : VIN, cession, CPI`,description:`Carte grise pas encore à votre nom ? Assurez avec le certificat de cession, le numéro VIN ou le CPI. Documents exacts, délais et démarches ANTS.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurer-voiture-sans-carte-grise`,datePublished:`2026-07-12`,dateModified:`2026-07-12`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurer une voiture sans carte grise`,item:`https://assutempo.fr/articles/assurer-voiture-sans-carte-grise`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Peut-on assurer une voiture avec seulement le certificat de cession ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. Le certificat de cession (Cerfa 15776), signé par le vendeur et l'acheteur, suffit généralement pour souscrire une assurance temporaire le temps que la carte grise soit établie à votre nom.`}},{"@type":`Question`,name:`Le numéro VIN suffit-il pour souscrire une assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, si le véhicule n'est pas encore immatriculé à votre nom. L'assureur peut établir un contrat provisoire à partir du numéro de série (VIN) et des caractéristiques techniques du véhicule.`}},{"@type":`Question`,name:`Quel est le délai pour mettre la carte grise à son nom après un achat ?`,acceptedAnswer:{"@type":`Answer`,text:`Un mois calendaire à compter de la date de cession, selon l'article R322-5 du Code de la route. Passé ce délai, l'amende forfaitaire est de 135 €, minorée à 90 € en paiement rapide.`}},{"@type":`Question`,name:`Peut-on rouler sans assurance pendant ce délai d'un mois ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. Le délai d'un mois concerne uniquement la carte grise. L'assurance, elle, est obligatoire dès le premier trajet, sans aucun délai de grâce (article L211-1 du Code des assurances).`}}]}],a={slug:`assurer-voiture-sans-carte-grise`,seo:{title:`Assurer une voiture sans carte grise : le guide`,description:`Carte grise pas encore à votre nom ? Assurez avec le certificat de cession, le numéro VIN ou le CPI. Documents exacts, délais et démarches ANTS.`,canonical:`https://assutempo.fr/articles/assurer-voiture-sans-carte-grise`,jsonLd:i},category:`Carte grise`,readTime:`6 min`,updatedDate:`12 juillet 2026`,author:`Evidence Assurances`,headline:`Assurer sans carte grise définitive : possible, et obligatoire avant de rouler`,answerCapsule:{answer:`Oui, vous pouvez assurer un véhicule avant que la carte grise soit à votre nom, avec le certificat de cession (Cerfa 15776), le numéro VIN ou le certificat provisoire d'immatriculation. C'est même obligatoire avant de prendre la route, dès la sortie du parking.`,facts:[{anchor:`1 mois`,text:`Délai calendaire dont dispose le nouveau propriétaire pour immatriculer le véhicule à son nom, à compter de la date de cession (article R322-5 du Code de la route).`},{anchor:`Cerfa 15776`,text:`Le certificat de cession, signé par le vendeur et l'acheteur, avec la carte grise barrée et datée, suffit pour rouler et pour s'assurer pendant la transition.`},{anchor:`1 à 4 mois`,text:`Durée de validité du certificat provisoire d'immatriculation : 1 mois pour un véhicule déjà immatriculé en France, jusqu'à 4 mois pour un CPI WW lié à un véhicule importé (service-public.fr).`}],updated:`12 juillet 2026`},sections:[{type:`text`,heading:`Peut-on rouler avec une voiture qui n'est pas encore à son nom ?`,paragraphs:[`Oui, temporairement, et c'est même prévu par les textes. La loi laisse un mois calendaire pour transférer la carte grise, le temps que le dossier passe par l'ANTS. Mais cette tolérance ne concerne que l'immatriculation. Elle ne dispense en rien de l'assurance, obligatoire dès le premier tour de roue, y compris pour le trajet retour depuis chez le vendeur.`,`Le point de friction, c'est justement là : comment assurer un véhicule dont la carte grise porte encore le nom d'un autre. La réponse tient en trois documents possibles, selon la situation exacte de l'achat.`]},{type:`alert`,heading:`Ce que dit le texte, chiffres à l'appui`,items:[`Délai légal d'un mois calendaire pour immatriculer un véhicule d'occasion à son nom (article R322-5 du Code de la route).`,`Amende forfaitaire de 135 € en cas de dépassement, minorée à 90 €, majorée à 375 € (contravention de 4e classe).`,`Certificat provisoire d'immatriculation (CPI) : valable 1 mois pour un véhicule déjà immatriculé en France, jusqu'à 4 mois pour un CPI WW.`,`Obligation d'assurance dès le premier trajet, sans lien avec le délai de carte grise (article L211-1 du Code des assurances).`],note:`Ces montants évoluent parfois : vérifiez-les sur service-public.fr avant toute démarche.`},{type:`text`,heading:`Quels documents l'assureur demande-t-il si la carte grise n'est pas encore à votre nom ?`,paragraphs:[`Le plus courant : le certificat de cession, Cerfa 15776, signé par l'ancien et le nouveau propriétaire, accompagné de la carte grise barrée et datée. Ce duo suffit pour la grande majorité des souscriptions, particulièrement pour un achat entre particuliers conclu le week-end.`,`Si le véhicule n'a même pas encore de plaque définitive, l'assureur peut se baser sur le numéro VIN, le numéro de série gravé sur le châssis, ainsi que sur les caractéristiques techniques du modèle. C'est le cas typique d'un véhicule neuf commandé en concession, ou d'une importation en cours de régularisation.`]},{type:`text`,heading:`Et si le dossier ANTS est déjà en cours via un garage ou un mandataire ?`,paragraphs:[`Certains professionnels, garages, mandataires, plateformes en ligne comme Certimat, montent la demande d'immatriculation à votre place, la saisie dans le SIV étant faite par un professionnel habilité par le Ministère de l'Intérieur. Dans ce cas, vous disposez souvent d'un accusé de dépôt ou d'un numéro de dossier avant même de recevoir le CPI. Ce justificatif ne remplace pas le certificat de cession pour l'assurance, mais il rassure sur l'avancement du côté administratif pendant que le contrat court sur la base du VIN.`,`Une nuance à connaître : tant que le CPI n'est pas délivré, le véhicule reste assuré sur la base des informations transmises au départ. Si une donnée change entre-temps, plaque définitive obtenue plus tôt que prévu par exemple, un simple message à l'assureur suffit à mettre le contrat à jour, sans repartir de zéro.`]},{type:`checklist`,heading:`Quelles pièces avoir sous la main pour assurer immédiatement ?`,intro:`Selon la situation, un seul de ces documents est généralement demandé :`,items:[`Le certificat de cession (Cerfa 15776), signé par le vendeur et l'acheteur`,`La carte grise barrée, datée et signée par l'ancien propriétaire`,`Le numéro VIN, si le véhicule n'a pas encore de plaque définitive`,`Le certificat provisoire d'immatriculation (CPI), si la démarche ANTS est déjà lancée`]},{type:`timeline`,heading:`Quel est le parcours type après un achat d'occasion le week-end ?`,steps:[{num:1,title:`Signature de la cession`,body:`Le Cerfa 15776 est signé par les deux parties, la carte grise est barrée, datée et signée. Le vendeur récupère un code de cession à 5 chiffres à transmettre à l'acheteur.`},{num:2,title:`Assurance souscrite dans la foulée`,body:`Avec le certificat de cession ou le VIN, l'attestation est délivrée immédiatement, sans attendre la carte grise définitive.`},{num:3,title:`Trajet retour couvert`,body:`Le véhicule roule légalement, assuré au nom du nouvel acheteur, avec la carte grise barrée à bord en attendant mieux.`},{num:4,title:`Immatriculation dans le mois`,body:`La demande est déposée sur l'ANTS ou via un professionnel habilité. Le certificat provisoire d'immatriculation autorise à circuler en attendant le titre définitif, envoyé par courrier.`}]},{type:`text`,heading:`Le certificat provisoire change-t-il quelque chose pour l'assurance ?`,paragraphs:[`Le CPI ne remplace pas l'assurance, il l'accompagne. Une fois délivré, il donne une immatriculation provisoire (plaques WW) que l'assureur peut inscrire au contrat à la place du numéro VIN. Rien n'oblige à attendre ce document pour s'assurer, mais il simplifie la mise à jour du dossier une fois obtenu.`],relatedLink:{text:`Le certificat provisoire d'immatriculation et les plaques WW, en détail`,href:`/le-certificat-provisoire-dimmatriculation-plaques-ww`}},{type:`text`,heading:`Que risque-t-on à rouler sans assurer le véhicule pendant cette transition ?`,paragraphs:[`Contrairement au mois de tolérance accordé pour la carte grise, l'assurance ne connaît aucun délai de grâce. Un contrôle sans preuve valable expose à une amende forfaitaire délictuelle, majorée en cas de retard de paiement, et jusqu'à 3 750 € devant un tribunal en cas de récidive ou de refus de se mettre en règle. Le véhicule peut aussi être immobilisé sur place.`,`Cette règle surprend parfois les acheteurs pressés : on pense volontiers avoir un mois de battement pour tout régulariser, alors que ce délai ne concerne que le papier gris, pas le contrat d'assurance.`],relatedLink:{text:`Rouler en attendant sa carte grise définitive`,href:`/articles/assurance-temporaire-rouler-en-attendant-carte-grise`}},{type:`callout`,title:`Le réflexe utile`,icon:`navigation`,text:`Gardez le certificat de cession et la carte grise barrée dans la boîte à gants jusqu'à réception du titre définitif. Ce sont ces deux papiers, avec l'attestation d'assurance, qui répondent à la quasi-totalité des questions en contrôle pendant la transition.`},{type:`text`,heading:`Faut-il finaliser la carte grise avant ou après avoir assuré le véhicule ?`,paragraphs:[`Dans l'ordre logique : assurer avant de prendre la route, puisque c'est la seule obligation sans délai. La carte grise, elle, se traite dans le mois qui suit, en ligne, via un professionnel habilité par le Ministère de l'Intérieur. Le certificat provisoire d'immatriculation permet de rouler pendant ce court intervalle, sans repousser le trajet retour au lendemain.`],relatedLink:{text:`Faire sa carte grise en ligne, CPI immédiat`,href:`/carte-grise`}}],faqItems:[{q:`Peut-on assurer une voiture avec seulement le certificat de cession ?`,a:`Oui. Le certificat de cession (Cerfa 15776), signé par le vendeur et l'acheteur, suffit généralement pour souscrire une assurance temporaire le temps que la carte grise soit établie à votre nom.`},{q:`Le numéro VIN suffit-il pour souscrire une assurance ?`,a:`Oui, si le véhicule n'est pas encore immatriculé à votre nom. L'assureur peut établir un contrat provisoire à partir du numéro de série (VIN) et des caractéristiques techniques du véhicule.`},{q:`Quel est le délai pour mettre la carte grise à son nom après un achat ?`,a:`Un mois calendaire à compter de la date de cession, selon l'article R322-5 du Code de la route. Passé ce délai, l'amende forfaitaire est de 135 €, minorée à 90 € en paiement rapide.`},{q:`Peut-on rouler sans assurance pendant ce délai d'un mois ?`,a:`Non. Le délai d'un mois concerne uniquement la carte grise. L'assurance, elle, est obligatoire dès le premier trajet, sans aucun délai de grâce (article L211-1 du Code des assurances).`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};